import heapq


def _ledger(revision_first, discounted):
    def solve(data):
        chosen = {}
        cutoff = data.get("cutoff", 10**9)
        for pos, event in enumerate(data["events"]):
            seq = event.get("sequence", 0)
            if seq > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(pos))
            if revision_first:
                key = (event.get("revision", 0), pos)
            else:
                key = (seq, event.get("revision", 0), pos)
            if event_id not in chosen or key > chosen[event_id][0]:
                chosen[event_id] = (key, event)

        balances = dict(data.get("opening", {}))
        mode = data["rounding"]

        def rounded(n, d):
            return (n + d // 2) // d if mode == "half_up" else n // d

        for _, event in chosen.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount), 10000)
            base = net if discounted else raw
            tax = rounded(base * event.get("tax_bp", 0), 10000)
            total = net + tax
            if event.get("kind") == "refund":
                total = -total
            key = event.get("account", "default") + "|" + event.get("currency", "USD")
            balances[key] = balances.get(key, 0) + total
        return {"balances": balances}
    return solve


def _dependencies(data):
    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    roots = data["roots"]
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    domains = []
    for name in names:
        versions = sorted(row["version"] for row in packages[name])
        domains.append([-1] + versions)

    best = None
    best_vector = None
    for vector in product(*domains):
        installed = {name: version for name, version in zip(names, vector) if version != -1}
        if any(version not in blocked.get(name, []) for name, version in []):
            continue
        if any(name not in installed or not (bounds[0] <= installed[name] <= bounds[1])
               for name, bounds in roots.items()):
            continue
        if any(name in installed and installed[name] != version for name, version in pins.items()):
            continue
        if any(version in blocked.get(name, []) for name, version in installed.items()):
            continue

        edges = {}
        valid = True
        for name, version in installed.items():
            row = next(r for r in packages[name] if r["version"] == version)
            active = [dep for dep in row.get("deps", [])
                      if not dep.get("feature") or dep["feature"] in features]
            edges[name] = []
            for dep in active:
                other = dep["name"]
                if other not in installed or not dep["min"] <= installed[other] <= dep["max"]:
                    valid = False
                    break
                edges[name].append(other)
            if not valid:
                break
        if not valid:
            continue

        reachable = set()
        stack = list(roots)
        while stack:
            name = stack.pop()
            if name in reachable:
                continue
            reachable.add(name)
            stack.extend(edges.get(name, []))
        if reachable != set(installed):
            continue

        state = {}
        def visit(name):
            if state.get(name) == 1:
                return False
            if state.get(name) == 2:
                return True
            state[name] = 1
            for other in edges.get(name, []):
                if not visit(other):
                    return False
            state[name] = 2
            return True
        if not all(visit(name) for name in installed):
            continue

        if best_vector is None or vector > best_vector:
            best_vector = vector
            best = installed
    return {"versions": best} if best is not None else {"error": "unsatisfiable"}


def _quota_intervals(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    options = [job for job in jobs if job["id"] not in blocked]
    if len(options) < k or not mandatory.issubset({job["id"] for job in options}):
        return {"error": "impossible"}

    best_value = None
    best_ids = None
    for subset in combinations(options, k):
        ids = {job["id"] for job in subset}
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in subset:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        events = []
        for job in subset:
            events.append((job["start"], 1))
            events.append((job["end"], -1))
        # Ends precede starts at equal times for half-open intervals.
        active = 0
        feasible = True
        for _, change in sorted(events, key=lambda item: (item[0], item[1])):
            active += change
            if active > 2:
                feasible = False
                break
        if not feasible:
            continue
        selected = sorted(ids)
        value = sum(job["value"] for job in subset)
        if (best_value is None or value > best_value or
                (value == best_value and selected < best_ids)):
            best_value, best_ids = value, selected
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


def _temporal_routes(data):
    required = data.get("required", [])
    bit_for = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    source = data["source"]
    initial_mask = bit_for.get(source, 0)
    start_state = (source, initial_mask, data["coupons"])
    best = {start_state: data["start"]}
    queue = [(data["start"], source, initial_mask, data["coupons"])]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    while queue:
        time, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if best.get(state) != time:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            choices = [(edge["duration"], remaining)]
            if remaining:
                duration = max(2, edge["duration"] - edge.get("discount", 0))
                choices.append((duration, remaining - 1))
            for duration, next_remaining in choices:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | bit_for.get(next_node, 0)
                next_state = (next_node, next_mask, next_remaining)
                if arrival < best.get(next_state, float("inf")):
                    best[next_state] = arrival
                    heapq.heappush(queue, (arrival, next_node, next_mask, next_remaining))
    return {"arrival": None}


